import{_ as a,o,c as t,a2 as n}from"./chunks/framework.iWwp2X7T.js";const u=JSON.parse('{"title":"诊断生命周期","description":"Mobile Inspector development documentation · 诊断生命周期","frontmatter":{"title":"诊断生命周期","description":"Mobile Inspector development documentation · 诊断生命周期"},"headers":[],"relativePath":"zh/reference/diagnosis.md","filePath":"zh/reference/diagnosis.md"}'),i={name:"zh/reference/diagnosis.md"};function r(s,e,d,c,l,p){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="诊断生命周期" tabindex="-1">诊断生命周期 <a class="header-anchor" href="#诊断生命周期" aria-label="Permalink to &quot;诊断生命周期&quot;">​</a></h1><h2 id="当前可用性" tabindex="-1">当前可用性 <a class="header-anchor" href="#当前可用性" aria-label="Permalink to &quot;当前可用性&quot;">​</a></h2><p><code>automaticDiagnosis</code> 为 false。Codex 适配器在 Git 和模型工作之前返回 <code>UNSUPPORTED_SANDBOX</code>，原因是有效无工具权限尚未认证。直接 Responses 适配器通过源码测试，但提供方兼容性未验收；配置不能豁免。自动修复 M4 未实现。</p><p>采集、事件浏览和只读 MCP 独立可用。普通启动、配对与记录不发模型请求。真实提供方尝试需要主动选择可信策略、owner 进程凭据及单独授权，失败不代表可以重试。</p><h2 id="观察与假设分开" tabindex="-1">观察与假设分开 <a class="header-anchor" href="#观察与假设分开" aria-label="Permalink to &quot;观察与假设分开&quot;">​</a></h2><p>事件保存事实，诊断是推测。事件状态有 open、diagnosing、diagnosed、needs-input 与 cancelled；任务状态为 queued、running、result、failed、cancelled。任务失败不创建应用缺陷，修复建议不是编辑许可或解决证明。</p><h2 id="有界编排" tabindex="-1">有界编排 <a class="header-anchor" href="#有界编排" aria-label="Permalink to &quot;有界编排&quot;">​</a></h2><p>每项目一个前台租约，全局最多四个。每项目一个执行任务、最多三个待处理，全局最多十二个待处理。五分钟期限覆盖准备与 runner；取消或超时发布终态，但在确认终止前保留容量。不定时重试，重复与静默窗口限制仍有效。</p><p>直接适配器最多一次有界 HTTPS POST，无工具、重定向、重试、回退或源码获取。结构结果校验拒绝虚构证据、路径越界和未知字段。安全失败可显示固定 stage/code/HTTP 状态，不显示提供方原文和正文。本地假提供方通过只证明本地分类。可从不调用模型的<a href="./../tutorials/diagnosis">合成实验</a>开始。</p>',9)])])}const _=a(i,[["render",r]]);export{u as __pageData,_ as default};
